create extension if not exists pgcrypto;

create table if not exists public.site_settings(
id int primary key default 1 check(id=1),business_name text not null default 'RS Trading & Property Hub',tagline text not null default 'PREMIUM FLATS • LAND & PLOTS • BUY • SELL • INVESTMENT',hero_kicker text not null default 'TRUST • LOCATION • GROWTH',hero_title text not null default 'Find Your Dream Property for Better Living & Greater Future',hero_subtitle text not null default 'Premium flats, land and plots, property marketing, consultancy, buy-sell support and investment-focused real estate services.',contact_phone text default '',contact_email text default '',address text default '',office_hours text default '',primary_color text default '#0c6b48',accent_color text default '#14a36d',meta_title text default 'RS Trading & Property Hub | Plots & Real Estate Projects',meta_description text default 'Explore premium flats, land and plots, property marketing, consultancy, buy-sell support and investment opportunities with RS Trading & Property Hub.');
insert into public.site_settings(id)values(1)on conflict(id)do nothing;

create table if not exists public.hero_slides(id bigint generated by default as identity primary key,title text not null,subtitle text default '',image_url text not null,cta_text text default 'Explore Projects',cta_link text default '/projects',sort_order int default 0,is_active boolean default true);
create table if not exists public.projects(id bigint generated by default as identity primary key,slug text unique not null,name text not null,location text default '',project_type text default '',summary text default '',description text default '',hero_image text default '',masterplan_image text default '',status text default 'Ongoing',starting_price text default '',total_plots int default 0,available_plots int default 0,latitude text default '',longitude text default '',amenities jsonb not null default '[]',legal_notes jsonb not null default '[]',sort_order int default 0,is_active boolean default true,is_featured boolean default false);
create table if not exists public.plots(id bigint generated by default as identity primary key,project_id bigint references public.projects(id) on delete cascade,plot_code text not null,plot_size text default '',road_width text default '',orientation text default '',price text default '',status text default 'Available',category text default 'Residential',notes text default '',is_active boolean default true);
create table if not exists public.team(id bigint generated by default as identity primary key,name text not null,role text default '',bio text default '',photo_url text default '',sort_order int default 0,is_active boolean default true);
create table if not exists public.reviews(id bigint generated by default as identity primary key,name text not null,company text default '',quote text not null,rating int default 5 check(rating between 1 and 5),verified boolean default false,sort_order int default 0,is_active boolean default true);
create table if not exists public.news(id bigint generated by default as identity primary key,title text not null,slug text unique not null,excerpt text default '',body text default '',image_url text default '',published_at text default '',sort_order int default 0,is_active boolean default true);
create table if not exists public.inquiries(id bigint generated by default as identity primary key,created_at timestamptz default now(),name text not null,email text not null,phone text,project_interest text,message text,type text default 'contact');
create table if not exists public.site_visits(id bigint generated by default as identity primary key,created_at timestamptz default now(),name text not null,email text not null,phone text not null,project_id bigint references public.projects(id),preferred_date date,notes text,status text default 'Pending');

do $$ declare t text; begin foreach t in array array['site_settings','hero_slides','projects','plots','team','reviews','news','inquiries','site_visits'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;

drop policy if exists "public settings" on public.site_settings;create policy "public settings" on public.site_settings for select to anon,authenticated using(true);
drop policy if exists "admin settings" on public.site_settings;create policy "admin settings" on public.site_settings for all to authenticated using(true)with check(true);

do $$ declare t text; begin foreach t in array array['hero_slides','projects','plots','team','reviews','news'] loop
 execute format('drop policy if exists "public_%s" on public.%I',t,t);
 execute format('create policy "public_%s" on public.%I for select to anon,authenticated using(is_active=true or auth.role()=''authenticated'')',t,t);
 execute format('drop policy if exists "admin_%s" on public.%I',t,t);
 execute format('create policy "admin_%s" on public.%I for all to authenticated using(true) with check(true)',t,t);
end loop; end $$;

drop policy if exists "public inquiries insert" on public.inquiries;create policy "public inquiries insert" on public.inquiries for insert to anon with check(true);
drop policy if exists "admin inquiries" on public.inquiries;create policy "admin inquiries" on public.inquiries for all to authenticated using(true)with check(true);
drop policy if exists "public site visits insert" on public.site_visits;create policy "public site visits insert" on public.site_visits for insert to anon with check(true);
drop policy if exists "admin site visits" on public.site_visits;create policy "admin site visits" on public.site_visits for all to authenticated using(true)with check(true);

